import {
    ArrayShape,
    IdentifierShape,
    PropertyAccessShape,
    type Source,
    TemplateExpressionShape,
} from '@servicenow/sdk-build-core'

export class PillShape extends PropertyAccessShape {
    private uiId: string
    private readonly path: string
    private type: string | undefined = undefined
    private parentTableName: string | undefined = undefined
    private columnName: string | undefined = undefined
    private reference: string | undefined = undefined

    constructor({ source, uiId, path, type }: { source: Source; uiId: string; path: string; type?: string }) {
        super({ source, elements: [uiId, path] })
        this.uiId = uiId
        this.path = path
        this.type = type
    }

    setType(type: string): void {
        this.type = type
    }

    getType(): string | undefined {
        return this.type
    }

    setParentTableName(parentTableName: string): void {
        this.parentTableName = parentTableName
    }

    getParentTableName(): string | undefined {
        return this.parentTableName
    }

    setColumnName(columnName: string): void {
        this.columnName = columnName
    }

    getColumnName(): string | undefined {
        return this.columnName
    }

    setReference(reference: string): void {
        this.reference = reference
    }

    getReference(): string | undefined {
        return this.reference
    }

    setRootIdentifier(arg0: string) {
        this.uiId = arg0
    }

    getRootIdentifier(): string {
        return this.uiId
    }

    override getValue(): string {
        // For schema references (empty path), don't include the dot
        // e.g., {{flowVariables}} or {{outputs}}
        // For property access, include the dot
        // e.g., {{flow_variable.someVar}} or {{trigger.current.sys_id}}
        const typePart = this.type !== undefined ? `|${this.type}` : ''
        const metaPart =
            this.parentTableName || this.columnName || this.reference
                ? `|meta:${this.parentTableName || ''}:${this.columnName || ''}:${this.reference || ''}`
                : ''
        return this.path ? `{{${this.uiId}.${this.path}${typePart}${metaPart}}}` : `{{${this.uiId}}}`
    }
}

export class PillTemplateShape extends TemplateExpressionShape {
    private readonly parts: ArrayShape

    constructor({ source, parts }: { source: Source; parts: unknown[] }) {
        super({ source, literalText: '', spans: [] })
        this.parts = new ArrayShape({ source, elements: parts })
    }

    getParts(): ArrayShape {
        return this.parts
    }
    override getValue(): string {
        const parts = this.parts.getElements(false)
        let result = ''

        for (const part of parts) {
            const value = part.getValue()
            if (typeof value === 'string') {
                // For string literals, add them directly
                result += value
            } else if (value instanceof PillShape) {
                result += value.getValue()
            }
        }

        return result
    }
}

export class ForEachItemShape extends IdentifierShape {
    private uiId: string
    private readonly path: string
    private type: string | undefined = undefined
    private parentTableName: string | undefined = undefined
    private columnName: string | undefined = undefined
    private reference: string | undefined = undefined

    constructor({ source, uiId, path }: { source: Source; uiId: string; path: string }) {
        super({ source, name: uiId })
        this.uiId = uiId
        this.path = path
    }

    setType(type: string): void {
        this.type = type
    }

    getType(): string | undefined {
        return this.type
    }

    setParentTableName(parentTableName: string): void {
        this.parentTableName = parentTableName
    }

    getParentTableName(): string | undefined {
        return this.parentTableName
    }

    setColumnName(columnName: string): void {
        this.columnName = columnName
    }

    getColumnName(): string | undefined {
        return this.columnName
    }

    setReference(reference: string): void {
        this.reference = reference
    }

    getReference(): string | undefined {
        return this.reference
    }

    getRootIdentifier(): string {
        return this.uiId
    }

    override getValue(): string {
        const typePart = this.type !== undefined ? `|${this.type}` : ''
        const metaPart =
            this.parentTableName || this.columnName || this.reference
                ? `|meta:${this.parentTableName || ''}:${this.columnName || ''}:${this.reference || ''}`
                : ''
        return `{{${this.uiId}.${this.path}${typePart}${metaPart}}}`
    }
}
